-- Honduras: municipios (GeoNames ADM2), by departamento.
--
-- One row per municipio. admin_region is the departamento; lat/lng is the GeoNames ADM2 point.
--
-- Source:      GeoNames country dumps, https://download.geonames.org/export/dump/
-- Licence:     Creative Commons Attribution 4.0, https://creativecommons.org/licenses/by/4.0/
-- Attribution: Contains data from GeoNames, CC BY 4.0
-- Downloaded:  2026-09-13
-- Generated by: node packages/db/scripts/build-municipalities.mjs --src <geonames dump dir>
--               (do not edit by hand; re-run the generator)
-- Rows:        298
-- Duplicates dropped on (country, admin_region, name): 0
-- Skipped (no usable point / no region): 0
--
-- Re-running corrects coordinates, timezone and population in place.

begin;

on conflict (country, admin_region, name) do update set lat = excluded.lat, lng = excluded.lng, timezone = excluded.timezone, population = excluded.population;

commit;
